package org.sleepwell.app;
import android.content.Context;import android.graphics.*;import android.view.*;
/** Original progress ring and two touch pads. Only actual two-pointer contact arms rotation. */
final class SpinView extends View {
 interface Contact{void changed(boolean both);}final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);final Contact listener;boolean both;int degrees;
 SpinView(Context context,Contact listener){super(context);this.listener=listener;setContentDescription("Hold a finger on each round touch pad while turning slowly. Use Math instead if turning is uncomfortable.");setFocusable(true);}
 @Override protected void onMeasure(int w,int h){setMeasuredDimension(MeasureSpec.getSize(w),Design.dp(getContext(),280));}
 void progress(int value){degrees=value;invalidate();}
 void release(){if(both){both=false;listener.changed(false);invalidate();}}
 @Override public boolean onTouchEvent(MotionEvent event){int action=event.getActionMasked();int left=-1,right=-1;if(action!=MotionEvent.ACTION_CANCEL&&action!=MotionEvent.ACTION_UP){for(int i=0;i<event.getPointerCount();i++){if(action==MotionEvent.ACTION_POINTER_UP&&i==event.getActionIndex())continue;float x=event.getX(i),y=event.getY(i),r=Design.dp(getContext(),48);if(Math.hypot(x-getWidth()*.25f,y-getHeight()*.78f)<=r)left=event.getPointerId(i);if(Math.hypot(x-getWidth()*.75f,y-getHeight()*.78f)<=r)right=event.getPointerId(i);}}boolean next=left>=0&&right>=0&&left!=right;if(next!=both){both=next;listener.changed(next);invalidate();}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)getParent().requestDisallowInterceptTouchEvent(false);else getParent().requestDisallowInterceptTouchEvent(true);return true;}
 @Override protected void onDetachedFromWindow(){release();super.onDetachedFromWindow();}
 @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float cx=getWidth()/2f,cy=getHeight()*.30f,r=Design.dp(getContext(),65);pen.setStyle(Paint.Style.STROKE);pen.setStrokeWidth(Design.dp(getContext(),12));pen.setColor(Design.SOFT);canvas.drawCircle(cx,cy,r,pen);pen.setColor(NightDialTokens.ACCENT);pen.setStrokeCap(Paint.Cap.ROUND);canvas.drawArc(cx-r,cy-r,cx+r,cy+r,-90,degrees,false,pen);pen.setStyle(Paint.Style.FILL);pen.setColor(Design.BROWN);pen.setTextAlign(Paint.Align.CENTER);pen.setTypeface(Design.font(getContext(),600));pen.setTextSize(Design.dp(getContext(),27));canvas.drawText(degrees+"°",cx,cy+Design.dp(getContext(),9),pen);float padY=getHeight()*.78f;pen.setColor(both?NightDialTokens.SECONDARY:Design.SOFT);canvas.drawCircle(getWidth()*.25f,padY,Design.dp(getContext(),40),pen);canvas.drawCircle(getWidth()*.75f,padY,Design.dp(getContext(),40),pen);pen.setColor(Design.BROWN);pen.setTextSize(Design.dp(getContext(),14));canvas.drawText("Hold",getWidth()*.25f,padY+Design.dp(getContext(),5),pen);canvas.drawText("Hold",getWidth()*.75f,padY+Design.dp(getContext(),5),pen);}
}
